sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
   var exp_discharge = new Date(g_form.getValue('expected_discharge_date'));
   var discharge = new Date(g_form.getValue('discharge_date'));
   var admit = new Date(newValue);
   if(!exp_discharge && !discharge) {
	return;
   }
   if(admit > exp_discharge || admit > discharge) {
	g_form.setValue('admission_date', '');
	g_form.showErrorBox('admission_date', 'Admission Date Cannot Be After Discharge or Expected Discharge Date');
   }

}
